<!DOCTYPE html>
<html>
<head>
    <title>2048</title>
    <style>
        body {
            background-color: #1e1e1e;
            color: #eee;
            font-family: monospace;
            text-align: center;
        }

        #board {
            display: grid;
            grid-template-columns: repeat(4, 80px);
            grid-gap: 5px;
            margin: 20px auto;
            width: 320px; /* Adjusted width */
        }

        .tile {
            background-color: #282c34;
            border: 1px solid #3e4451;
            font-size: 3em;
            text-align: center;
            line-height: 80px; /* Match tile height */
        }

        #score {
            font-size: 2em;
            margin-bottom: 20px;
        }

        button {
            background-color: #3e4451;
            border: none;
            color: #eee;
            padding: 10px 20px;
            font-size: 1.2em;
            cursor: pointer;
            border-radius: 5px;
        }

        button:hover {
            background-color: #434c5e;
        }
    </style>
</head>
<body>
    <h1>2048</h1>
    <div id="score">Score: 0</div>
    <table id="board">
        <tr>
            <td class="tile"></td>
            <td class="tile"></td>
            <td class="tile"></td>
            <td class="tile"></td>
        </tr>
        <tr>
            <td class="tile"></td>
            <td class="tile"></td>
            <td class="tile"></td>
            <td class="tile"></td>
        </tr>
        <tr>
            <td class="tile"></td>
            <td class="tile"></td>
            <td class="tile"></td>
            <td class="tile"></td>
        </tr>
        <tr>
            <td class="tile"></td>
            <td class="tile"></td>
            <td class="tile"></td>
            <td class="tile"></td>
        </tr>
    </table>
    <button id="reset">New Game</button>

    <script>
        const board = document.getElementById('board');
        const scoreElement = document.getElementById('score');
        const resetButton = document.getElementById('reset');

        let boardData = [];
        let score = 0;

        function initGame() {
            boardData = Array(4).fill(null).map(() => Array(4).fill(0));
            placeNewTiles();
            updateBoardDisplay();
            scoreElement.textContent = `Score: ${score}`;
        }

        function placeNewTiles() {
            let emptyCells = [];
            for (let i = 0; i < 4; i++) {
                for (let j = 0; j < 4; j++) {
                    if (boardData[i][j] === 0) {
                        emptyCells.push([i, j]);
                    }
                }
            }

            if (emptyCells.length > 0) {
                const randomIndex = Math.floor(Math.random() * emptyCells.length);
                const [row, col] = emptyCells[randomIndex];
                boardData[row][col] = Math.random() < 0.9 ? 2 : 4;
            }
        }

        function updateBoardDisplay() {
            for (let i = 0; i < 4; i++) {
                for (let j = 0; j < 4; j++) {
                    const tile = board.rows[i].cells[j];
                    tile.textContent = boardData[i][j] === 0 ? '' : boardData[i][j];
                    tile.style.backgroundColor = boardData[i][j] === 0 ? '#282c34' : ''; // Ensure background remains dark
                }
            }
        }

        function move(direction) {
            let moved = false;
            const originalBoard = JSON.parse(JSON.stringify(boardData)); // Deep copy

            switch (direction) {
                case 'left':
                    for (let i = 0; i < 4; i++) {
                        moved = moved || moveRow(i, 'left');
                    }
                    break;
                case 'right':
                    for (let i = 0; i < 4; i++) {
                        moved = moved || moveRow(i, 'right');
                    }
                    break;
                case 'up':
                    for (let j = 0; j < 4; j++) {
                        moved = moved || moveCol(j, 'up');
                    }
                    break;
                case 'down':
                    for (let j = 0; j < 4; j++) {
                        moved = moved || moveCol(j, 'down');
                    }
                    break;
            }

            if (moved && JSON.stringify(boardData) !== JSON.stringify(originalBoard)) {
                placeNewTiles();
            }

            return moved;
        }

        function moveRow(row, direction) {
            let newRow = boardData[row].filter(tile => tile !== 0);
            let index = 0;
            for (let i = 0; i < 4; i++) {
                if (boardData[row][i] !== 0) {
                    if (direction === 'left') {
                        while (index < newRow.length && boardData[row][index] === 0) {
                            index++;
                        }
                        if (index < newRow.length && boardData[row][index] === newRow[newRow.length - 1]) {
                            boardData[row][index] = newRow[newRow.length - 1] * 2;
                            score += newRow[newRow.length - 1] * 2;
                            newRow = newRow.slice(0, newRow.length - 1);
                        }

                    } else { // direction === 'right'
                        while (index < newRow.length && boardData[row][index] === 0) {
                            index++;
                        }
                         if (index < newRow.length && boardData[row][index] === newRow[0]) {
                             boardData[row][index] = newRow[0] * 2;
                             newRow = newRow.slice(1);
                         }


                    }
                }
            }

            for (let i = 0; i < newRow.length; i++) {
                if (i < boardData[row].length) {
                    boardData[row][i] = newRow[i];
                } else {
                    boardData[row][i] = 0;
                }
            }

             return true;
        }

        function moveCol(col, direction) {
             let transposedBoardData = [];
             for (let i=0; i<4; i++) {
                 transposedBoardData.push([]);
                 for(let j=0; j < 4; j++){
                     transposedBoardData[i].push(boardData[j][col]);
                 }
             }

            let newCol = transposedBoardData[col].filter(tile => tile !== 0);
            let index = 0;
            for (let i = 0; i < 4; i++) {
                if (transposedBoardData[col][i] !== 0) {
                    if (direction === 'up') {
                        while (index < newCol.length && transposedBoardData[i][index] === 0) {
                            index++;
                        }
                        if (index < newCol.length && transposedBoardData[i][index] === newCol[newCol.length - 1]) {
                            transposedBoardData[i][index] = newCol[newCol.length - 1] * 2;
                            score += newCol[newCol.length - 1] * 2;
                            newCol = newCol.slice(0, newCol.length - 1);
                        }

                    } else { // direction === 'down'
                         while (index < newCol.length && transposedBoardData[i][index] === 0) {
                             index++;
                         }
                          if (index < newCol.length && transposedBoardData[i][index] === newCol[0]) {
                              transposedBoardData[i][index] = newCol[0] * 2;
                              newCol = newCol.slice(1);
                          }

                    }
                }
            }


             for (let i = 0; i < 4; i++) {
                 boardData[i][col] = newCol[i];
             }


            return true;
        }



        resetButton.addEventListener('click', initGame);

        window.game = {
            size: 4,
            reset: initGame,
            move: move,
            board: () => boardData,
            setBoard: setBoard,
            score: () => score
        };

        function setBoard(arr) {
            boardData = arr;
            updateBoardDisplay();
        }
    </script>
</body>
</html>
